import{_ as a,C as s,o as r,c as E,a2 as e,b as l,w as d,a as i,E as h,a3 as n}from"./chunks/framework.CFuv5BrO.js";const _=JSON.parse('{"title":"Hearth OS｜意图识别路由：执行器是如何被自动选中的","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/意图识别路由与执行器自动选择.md","filePath":"architecture/意图识别路由与执行器自动选择.md","lastUpdated":null}'),c={name:"architecture/意图识别路由与执行器自动选择.md"};function B(A,t,b,u,p,g){const o=s("Mermaid");return r(),E("div",null,[t[1]||(t[1]=e('<h1 id="hearth-os-意图识别路由-执行器是如何被自动选中的" tabindex="-1">Hearth OS｜意图识别路由：执行器是如何被自动选中的 <a class="header-anchor" href="#hearth-os-意图识别路由-执行器是如何被自动选中的" aria-label="Permalink to &quot;Hearth OS｜意图识别路由：执行器是如何被自动选中的&quot;">​</a></h1><blockquote><p>基于实际源码梳理（未参考项目文档） · 整理于 2026-11-13 本文只讲设计思路，不贴源代码。</p></blockquote><hr><h2 id="一、先分清两条「路由」" tabindex="-1">一、先分清两条「路由」 <a class="header-anchor" href="#一、先分清两条「路由」" aria-label="Permalink to &quot;一、先分清两条「路由」&quot;">​</a></h2><p>项目里有两个名字相近、但完全独立的模块，容易混淆：</p><table tabindex="0"><thead><tr><th>模块</th><th>做什么</th><th>是否选择执行器</th></tr></thead><tbody><tr><td>外部消息入口分拣（<code>intake-router.ts</code>）</td><td>用正则把来信分成「忽略 / 需关注 / 任务 / 闲聊」，只写一条决策记录</td><td>❌ 否</td></tr><tr><td>对话链路（<code>chat.ts</code> → <code>executors.ts</code> → <code>chat-routes.ts</code>）</td><td>判断用户这句话要不要派单，并自动挑一个执行器去跑</td><td>✅ 是，本文主角</td></tr></tbody></table><blockquote><p>前者是「注意力分拣」，后者才是「执行器自动选择」。下面只讲后者。</p></blockquote><hr><h2 id="二、一句话总览" tabindex="-1">二、一句话总览 <a class="header-anchor" href="#二、一句话总览" aria-label="Permalink to &quot;二、一句话总览&quot;">​</a></h2><p>核心设计是<strong>把三个问题彻底拆开，逐层收窄</strong>：</p><ol><li><strong>要不要执行？</strong> —— 语义判断，交给模型，但用规则双向纠错。</li><li><strong>该推荐谁？</strong> —— 纯关键词规则，不经过模型。</li><li><strong>现在真能派给它吗？</strong> —— 结合开关、健康状态、能力约束做最终裁决。</li></ol>',11)),(r(),l(n,null,{default:d(()=>[h(o,{id:"mermaid-83",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%E7%94%A8%E6%88%B7%E6%B6%88%E6%81%AF%3Cbr%2F%3E%E6%96%87%E6%9C%AC%20%C2%B7%20%E9%99%84%E4%BB%B6%20%C2%B7%20%E7%BD%91%E5%9D%80%20%C2%B7%20%E4%BC%9A%E8%AF%9D%E8%AE%BE%E7%BD%AE%5D%20--%3E%20B%7B%E7%AC%AC%201%20%E5%B1%82%20%E6%84%8F%E5%9B%BE%E8%AF%86%E5%88%AB%3Cbr%2F%3E%E8%A6%81%E7%9A%84%E6%98%AF%E5%9B%9E%E7%AD%94%20%E8%BF%98%E6%98%AF%E6%96%B0%E4%BA%A7%E7%89%A9%7D%0A%20%20%20%20B%20--%3E%7Cchat%7C%20C%5B%E7%9B%B4%E6%8E%A5%E7%94%B1%E8%81%8A%E5%A4%A9%E6%A8%A1%E5%9E%8B%E5%9B%9E%E7%AD%94%5D%0A%20%20%20%20B%20--%3E%7Ctask%7C%20D%5B%E7%AC%AC%202%20%E5%B1%82%20%E6%89%A7%E8%A1%8C%E8%AE%A1%E5%88%92%3Cbr%2F%3E%E8%A7%84%E5%88%99%E5%8C%B9%E9%85%8D%E5%87%BA%E6%8E%A8%E8%8D%90%E6%89%A7%E8%A1%8C%E5%99%A8%E4%B8%8E%E8%83%BD%E5%8A%9B%E6%A0%87%E7%AD%BE%5D%0A%20%20%20%20D%20--%3E%20E%7B%E7%AC%AC%203%20%E5%B1%82%20%E5%8F%AF%E8%A1%8C%E6%80%A7%E8%A3%81%E5%86%B3%3Cbr%2F%3E%E5%B7%B2%E5%90%AF%E7%94%A8%20%C2%B7%20%E5%8F%AF%E7%94%A8%20%C2%B7%20%E6%94%AF%E6%8C%81%E8%83%BD%E5%8A%9B%7D%0A%20%20%20%20E%20--%3E%7C%E7%94%A8%E6%88%B7%E5%B7%B2%E9%94%81%E5%AE%9A%E4%B8%94%E4%B8%8D%E6%BB%A1%E8%B6%B3%7C%20F%5B%E6%8B%92%E7%BB%9D%E6%B4%BE%E5%8D%95%20%E5%B9%B6%E8%AF%B4%E6%98%8E%E5%85%B7%E4%BD%93%E5%8E%9F%E5%9B%A0%5D%0A%20%20%20%20E%20--%3E%7C%E8%87%AA%E5%8A%A8%E5%8C%B9%E9%85%8D%20%E9%A6%96%E9%80%89%E4%B8%8D%E6%BB%A1%E8%B6%B3%7C%20G%5B%E6%8C%89%E5%9B%9E%E9%80%80%E9%A1%BA%E5%BA%8F%E6%8D%A2%E4%BA%BA%20%E8%AE%B0%E5%BD%95%E6%94%B9%E6%B4%BE%E6%9D%A5%E6%BA%90%5D%0A%20%20%20%20E%20--%3E%7C%E4%B8%89%E9%A1%B9%E5%85%A8%E6%BB%A1%E8%B6%B3%7C%20H%5B%E6%B4%BE%E5%87%BA%E4%BB%BB%E5%8A%A1%3Cbr%2F%3E%E5%86%99%E5%85%A5%E6%89%A7%E8%A1%8C%E5%99%A8%20%E4%BB%BB%E5%8A%A1%E7%B1%BB%E5%9E%8B%20%E6%9D%83%E9%99%90%E8%BE%B9%E7%95%8C%5D%0A"})]),fallback:d(()=>[...t[0]||(t[0]=[i(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=e('<p>最值得注意的一点：<strong>模型只负责「要不要干活」这一个问题，选哪个执行器完全由确定性规则决定</strong>。这样结果可预测、可单测，也不会因为模型幻觉选到一个不存在或没安装的执行器。</p><hr><h2 id="三、第-1-层-意图识别-要不要执行" tabindex="-1">三、第 1 层｜意图识别：要不要执行 <a class="header-anchor" href="#三、第-1-层-意图识别-要不要执行" aria-label="Permalink to &quot;三、第 1 层｜意图识别：要不要执行&quot;">​</a></h2><p><strong>输出只有一个二分类：<code>chat</code>（用文字回答）或 <code>task</code>（派单执行）。</strong></p><h3 id="硬规则先行" tabindex="-1">硬规则先行 <a class="header-anchor" href="#硬规则先行" aria-label="Permalink to &quot;硬规则先行&quot;">​</a></h3><ul><li><strong>带附件 → 直接判 <code>task</code></strong>：聊天模型读不到附件内容，只能交给执行器处理。</li><li><strong>没配置聊天模型 → 跳过模型</strong>：直接退回关键词启发式。</li></ul><h3 id="模型路由器" tabindex="-1">模型路由器 <a class="header-anchor" href="#模型路由器" aria-label="Permalink to &quot;模型路由器&quot;">​</a></h3><p>用一段专门的提示词，要求模型<strong>只输出一个 JSON</strong>（动作 / 标题 / 原因），温度 0、限 160 tokens、20 秒超时。判据写得非常明确：</p><blockquote><p>用户要的是「解释」，还是「一个新的产物」？网址和附件只是上下文，本身不等于任务。</p></blockquote><p>提示词里还配了四组正反示例，例如「介绍一下这个 GitHub 项目」是问答，而「帮我总结这个网页并保存成文件」是任务。</p><h3 id="双向校正-最用心的部分" tabindex="-1">双向校正（最用心的部分） <a class="header-anchor" href="#双向校正-最用心的部分" aria-label="Permalink to &quot;双向校正（最用心的部分）&quot;">​</a></h3><p>模型判完不算数，规则还会从两个方向纠偏：</p><table tabindex="0"><thead><tr><th>方向</th><th>触发条件</th><th>纠正动作</th></tr></thead><tbody><tr><td>防「过度派单」</td><td>模型判 <code>task</code>，但带网址/附件且文本是「介绍、是什么、为什么、怎么样」这类解释性提问</td><td>拉回 <code>chat</code></td></tr><tr><td>防「漏派任务」</td><td>模型判 <code>chat</code>，但命中强制任务规则：要截图、要读取自己仓库的 PR、或用户已显式选了执行器且关键词像干活</td><td>拉回 <code>task</code></td></tr></tbody></table><h3 id="层层降级-永不硬失败" tabindex="-1">层层降级，永不硬失败 <a class="header-anchor" href="#层层降级-永不硬失败" aria-label="Permalink to &quot;层层降级，永不硬失败&quot;">​</a></h3><p>模型 JSON 解析失败、超时、抛异常 → 一律回落到关键词启发式。启发式同样有正反两组：</p><ul><li>「怎么 / 为什么 / 什么是 / 请问」开头的解释性问句 → 优先判 <code>chat</code>；</li><li>「帮我 / 生成 / 修复 / 导出 / 运行 / 整理」等执行类动词 → 判 <code>task</code>。</li></ul><blockquote><p>小结：模型负责语义，规则负责兜底与纠错，两者互相拉扯，既不误派也不漏派。</p></blockquote><hr><h2 id="四、第-2-层-执行计划-推荐谁来做" tabindex="-1">四、第 2 层｜执行计划：推荐谁来做 <a class="header-anchor" href="#四、第-2-层-执行计划-推荐谁来做" aria-label="Permalink to &quot;四、第 2 层｜执行计划：推荐谁来做&quot;">​</a></h2><p><strong>这一层完全不用模型，是按优先级短路匹配的确定性规则。</strong></p><table tabindex="0"><thead><tr><th>优先级</th><th>命中特征</th><th>推荐执行器</th><th>任务类型</th><th>附带约束</th></tr></thead><tbody><tr><td>1</td><td>截图 / 截屏 / 桌面画面</td><td>原生执行器</td><td>通用</td><td>能力标签「桌面截图」，预期产出图片</td></tr><tr><td>2</td><td>GitHub / PR / 拉取请求</td><td>Codex</td><td>工作区</td><td>能力标签「GitHub」+ 网络白名单（github.com 等）</td></tr><tr><td>3</td><td>代码 / 仓库 / 测试 / 构建 / 重构 / 修复 等</td><td>Codex</td><td>工作区</td><td>预期产出结果文档</td></tr><tr><td>4</td><td>其余（文档、整理、分析、网页任务）</td><td>原生执行器</td><td>通用</td><td>预期产出结果文档</td></tr></tbody></table><p>产出的「执行计划」包含四件事：</p><ul><li><strong>推荐执行器</strong></li><li><strong>任务类型</strong>（通用 / 工作区）</li><li><strong>预期产物</strong>（结果文档或图片）</li><li><strong>能力标签与网络白名单</strong></li></ul><blockquote><p>关键设计：能力标签不只是选人依据，它同时决定权限边界。意图识别在这里直接连到了安全策略，而不是先选人再补权限。</p></blockquote><hr><h2 id="五、第-3-层-可行性裁决-最终谁真的跑" tabindex="-1">五、第 3 层｜可行性裁决：最终谁真的跑 <a class="header-anchor" href="#五、第-3-层-可行性裁决-最终谁真的跑" aria-label="Permalink to &quot;五、第 3 层｜可行性裁决：最终谁真的跑&quot;">​</a></h2><p>推荐值不等于最终值。<strong>首选 = 用户锁定值 ?? 计划推荐值</strong>，然后经过三重过滤：</p><ol><li><p><strong>是否启用</strong> 会话级开关。默认开启原生 / Codex / Hermes；DeepSeek 需要绑定模型档案，外部 CLI 需要检测到已安装或已配置命令。设置分三层：<strong>全局偏好 → 会话设置 → 单条消息临时覆盖</strong>（临时覆盖不落库）。</p></li><li><p><strong>是否可用</strong> 健康探测结果。本质是跑一个最小探针、要求执行器返回固定应答；原生执行器默认恒可用，其余都要真实探测通过。</p></li><li><p><strong>是否支持该能力</strong> 能力白名单。例如「桌面截图」只允许原生执行器；「GitHub」允许多数执行器，但不含部分外部 CLI。</p></li></ol><h3 id="两种模式-行为完全相反" tabindex="-1">两种模式，行为完全相反 <a class="header-anchor" href="#两种模式-行为完全相反" aria-label="Permalink to &quot;两种模式，行为完全相反&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>自动匹配（默认）</th><th>用户锁定执行器</th></tr></thead><tbody><tr><td>首选不满足条件</td><td>按固定顺序回退到第一个三项全满足的执行器</td><td><strong>绝不换人</strong>，直接拒绝派单</td></tr><tr><td>回退顺序</td><td>DeepSeek Harness → Codex → 原生 → Hermes → Qoder → WorkBuddy → Kimi</td><td>无</td></tr><tr><td>用户看到什么</td><td>返回「改派自谁 + 中文原因」，助手消息里说明已自动改由谁接管</td><td>提示具体原因（已关闭 / 不可用 / 不支持此能力），并引导切回自动匹配</td></tr><tr><td>聊天是否仍可用</td><td>是</td><td>是，拒派只影响任务</td></tr></tbody></table><p>一个巧妙的细节：<strong>若用户偏好与计划推荐不一致，回退队列会把「计划推荐的执行器」插到队首</strong>，保证语义上最合适的人选优先于机械顺序。</p><hr><h2 id="六、结果如何落地与复用" tabindex="-1">六、结果如何落地与复用 <a class="header-anchor" href="#六、结果如何落地与复用" aria-label="Permalink to &quot;六、结果如何落地与复用&quot;">​</a></h2><p><strong>落地</strong></p><ul><li>裁决结果通过 SSE 的 <code>routing</code> 事件回传前端，包含动作、计划、偏好、锁定标记、改派来源 —— <strong>决策过程对用户可观测</strong>。</li><li>判为任务时创建任务，写入执行器、任务类型、预期产物、网络白名单；发生改派时，助手消息会明说「原执行器不可用，已自动改由 X 接管」。</li><li>判为问答时走普通聊天流，前面的执行器计算不影响回答。</li></ul><p><strong>同一套裁决逻辑在另外三处复用</strong></p><table tabindex="0"><thead><tr><th>场景</th><th>为什么要重新裁决</th></tr></thead><tbody><tr><td>任务提案确认时</td><td>等待用户确认期间，执行器可能已被关闭或探测失败</td></tr><tr><td>调度器取执行器</td><td>直接用任务上已固化的值；缺省时按「有模板 → Codex，否则 → 原生」兜底</td></tr><tr><td>运行中故障接管</td><td>仅当确属执行器故障，才按同一回退顺序换人；<strong>锁定状态、评测任务、超过接管次数一律禁止自动切换</strong></td></tr></tbody></table><hr><h2 id="七、走一个完整例子" tabindex="-1">七、走一个完整例子 <a class="header-anchor" href="#七、走一个完整例子" aria-label="Permalink to &quot;七、走一个完整例子&quot;">​</a></h2><p>用户说：「<strong>请你审核我的 GitHub 仓库中目前开着的 PR，列出需要回复或 rebase 的</strong>」</p><ol><li><strong>意图识别</strong>：无附件；模型可能因「列出」判成问答，但强制规则识别到「PR + 指向自己仓库」→ 纠正为 <code>task</code>。</li><li><strong>执行计划</strong>：命中 GitHub 关键词 → 推荐 Codex，任务类型「工作区」，能力标签「GitHub」，网络白名单放行 github.com 与 api.github.com。</li><li><strong>可行性裁决</strong>： <ul><li>若用户没锁定执行器，且 Codex 被关闭 → 按回退顺序找到原生执行器（它支持 GitHub 能力）→ 改派，并记录「改派自 Codex」。</li><li>若用户显式锁定了原生执行器 → 直接用原生执行器，不换人；若它被关闭，则拒绝派单并提示原因。</li></ul></li><li><strong>落地</strong>：创建任务，带上执行器、任务类型、预期产物与网络白名单，前端同时收到 <code>routing</code> 事件展示决策依据。</li></ol><hr><h2 id="八、这套设计的三个亮点" tabindex="-1">八、这套设计的三个亮点 <a class="header-anchor" href="#八、这套设计的三个亮点" aria-label="Permalink to &quot;八、这套设计的三个亮点&quot;">​</a></h2><ol><li><strong>职责分离</strong>：模型只做语义二分类，选执行器交给确定性规则 —— 可预测、可测试、不受模型幻觉影响。</li><li><strong>层层降级，永不硬失败</strong>：模型 → 关键词 → 默认问答；首选 → 有序回退 → 明确拒绝并给出可操作提示。任何一环出错都不阻塞聊天。</li><li><strong>用户显式意图优先级最高</strong>：手动选择等于锁定，连自动改派都会被抑制；同时这个选择还会反向增强「这是任务」的判定，避免把明确的执行请求当成闲聊。</li></ol><hr><h2 id="附-源码定位索引" tabindex="-1">附：源码定位索引 <a class="header-anchor" href="#附-源码定位索引" aria-label="Permalink to &quot;附：源码定位索引&quot;">​</a></h2><table tabindex="0"><thead><tr><th>职责</th><th>文件</th></tr></thead><tbody><tr><td>意图识别（二分类 + 双向校正 + 启发式）</td><td><code>apps/server/src/chat.ts</code></td></tr><tr><td>执行计划（规则匹配）</td><td><code>apps/server/src/chat.ts</code></td></tr><tr><td>任务意图关键词（截图 / GitHub / 代码 / 联网）</td><td><code>apps/server/src/task-intent.ts</code></td></tr><tr><td>执行器清单、能力白名单、回退顺序、两种裁决</td><td><code>apps/server/src/executors.ts</code></td></tr><tr><td>主链路编排（串起三层、SSE 回传、创建任务）</td><td><code>apps/server/src/chat-routes.ts</code></td></tr><tr><td>执行器健康探测</td><td><code>apps/server/src/executor-runtime.ts</code></td></tr><tr><td>提案确认时重新裁决</td><td><code>apps/server/src/service.ts</code></td></tr><tr><td>调度取执行器、失败接管</td><td><code>apps/server/src/scheduler.ts</code></td></tr><tr><td>外部消息入口分拣（非执行器路由）</td><td><code>apps/server/src/intake-router.ts</code></td></tr></tbody></table>',47))])}const k=a(c,[["render",B]]);export{_ as __pageData,k as default};
